import sys
import json
import requests

def groq_chat(prompt: str, model: str = "mixtral-8x7b-32768", api_key: str | None = None) -> str:
    """Send *prompt* to Groq's chat completion endpoint and return the generated text.
    Raises RuntimeError on missing key, HTTP error, or unexpected response format.
    """
    # 1️⃣ Get API key
    if api_key is None:
        api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        raise RuntimeError("GROQ_API_KEY not set. Provide it via env or function argument.")

    # 2️⃣ Prepare request
    url = "https://api.groq.com/openai/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "temperature": 0.7,
    }

    # 3️⃣ Send request
    try:
        resp = requests.post(url, headers=headers, json=payload, timeout=30)
        resp.raise_for_status()
    except requests.RequestException as exc:
        raise RuntimeError(f"Request to Groq failed: {exc}") from exc

    # 4️⃣ Parse response
    try:
        data = resp.json()
        return data["choices"][0]["message"]["content"].strip()
    except (KeyError, IndexError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Invalid response format from Groq: {exc}") from exc

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python groq_call.py '<prompt>'")
        sys.exit(1)
    user_prompt = sys.argv[1]
    try:
        answer = groq_chat(user_prompt)
        print("Groq response:\n", answer)
    except RuntimeError as err:
